import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.Boholvbs.js";const s="/docs/assets/ai-context-panel.FZhRHNtH.png",i="/docs/assets/ai-context-suggestions.CSTagse6.png",r="/docs/assets/ai-context-modal.DRF-zxAA.png",f=JSON.parse('{"title":"AI Context Assistant — Editorial Suggestions","description":"","frontmatter":{},"headers":[],"relativePath":"ai-context-assistant.md","filePath":"ai-context-assistant.md"}'),l={name:"ai-context-assistant.md"};function h(c,e,g,p,d,u){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-context-assistant-—-editorial-suggestions" tabindex="-1">AI Context Assistant — Editorial Suggestions <a class="header-anchor" href="#ai-context-assistant-—-editorial-suggestions" aria-label="Permalink to &quot;AI Context Assistant — Editorial Suggestions&quot;">​</a></h1><p>The AI Context Assistant is a Gutenberg sidebar panel that helps you enrich your articles with AI-suggested paragraphs and references to related content from your site&#39;s knowledge base.</p><p>See <a href="./ai-in-jeo">AI in JEO</a> to learn how RAG, agents, and conversation memory power this feature.</p><h2 id="opening-the-panel" tabindex="-1">Opening the panel <a class="header-anchor" href="#opening-the-panel" aria-label="Permalink to &quot;Opening the panel&quot;">​</a></h2><ol><li>Open or create a post in the Gutenberg editor (the post type must be enabled in <strong>JEO Settings → General</strong>).</li><li>In the <strong>Document</strong> sidebar, find the <strong>AI Context</strong> panel.</li><li>If the panel is collapsed, click its title to expand it.</li></ol><h2 id="generating-suggestions" tabindex="-1">Generating suggestions <a class="header-anchor" href="#generating-suggestions" aria-label="Permalink to &quot;Generating suggestions&quot;">​</a></h2><p>Click <strong>Generate Suggestions</strong>. The AI will analyze your article&#39;s content and the site&#39;s vectorized article archive to produce:</p><ul><li><strong>Suggested paragraphs</strong> — ready-to-insert text blocks that complement your article. Paragraphs may include inline formatting (bold, italic) and links to related articles.</li><li><strong>Related references</strong> — articles from your knowledge base that are relevant to the topic.</li></ul><p>The generation is <strong>not automatic</strong> — you control when it runs to avoid unnecessary API calls.</p><p><img src="'+s+'" alt="AI Context panel — idle state"></p><h2 id="using-suggested-paragraphs" tabindex="-1">Using suggested paragraphs <a class="header-anchor" href="#using-suggested-paragraphs" aria-label="Permalink to &quot;Using suggested paragraphs&quot;">​</a></h2><p>Each suggested paragraph has two actions:</p><h3 id="insert-into-article" tabindex="-1">Insert into article <a class="header-anchor" href="#insert-into-article" aria-label="Permalink to &quot;Insert into article&quot;">​</a></h3><p>Click <strong>Insert into article</strong> to add the paragraph as a Gutenberg <code>core/paragraph</code> block at the end of the document. Inline formatting and links are preserved. Once inserted, the button changes to <strong>Inserted</strong> to prevent duplicates.</p><h3 id="copy" tabindex="-1">Copy <a class="header-anchor" href="#copy" aria-label="Permalink to &quot;Copy&quot;">​</a></h3><p>Click <strong>Copy</strong> to copy the paragraph as rich text (HTML with links) to your clipboard. You can then paste it anywhere — the WordPress editor, Google Docs, Word, etc. The copy uses a triple-fallback mechanism for maximum compatibility:</p><ol><li>Modern <code>ClipboardItem</code> API (HTML + plain text)</li><li>DOM selection + <code>execCommand(&#39;copy&#39;)</code> (works in Gutenberg iframes)</li><li>Plain text only (universal fallback)</li></ol><p><img src="'+i+'" alt="AI Context panel — suggestions and chat"></p><h2 id="refining-with-chat" tabindex="-1">Refining with chat <a class="header-anchor" href="#refining-with-chat" aria-label="Permalink to &quot;Refining with chat&quot;">​</a></h2><p>After the initial generation, you can refine suggestions through the chat textarea:</p><ul><li><strong>&quot;Make it shorter&quot;</strong> — condenses the suggested paragraphs.</li><li><strong>&quot;Focus on environmental impact&quot;</strong> — rewrites with a specific angle.</li><li><strong>&quot;Add more historical context&quot;</strong> — expands with additional background.</li><li><strong>&quot;Include data about the Amazon region&quot;</strong> — adds region-specific content.</li></ul><p>Press <strong>Ctrl+Enter</strong> or click <strong>Send</strong> to submit your message.</p><h3 id="retry" tabindex="-1">Retry <a class="header-anchor" href="#retry" aria-label="Permalink to &quot;Retry&quot;">​</a></h3><p>Click <strong>Retry</strong> to ask the AI to generate new suggestions without typing a message. Useful when you want a different take on the same topic.</p><h3 id="clear" tabindex="-1">Clear <a class="header-anchor" href="#clear" aria-label="Permalink to &quot;Clear&quot;">​</a></h3><p>Click <strong>Clear</strong> to reset the entire conversation and remove all suggestions. A new conversation starts fresh on the next &quot;Generate Suggestions&quot; click.</p><h2 id="expanding-the-panel" tabindex="-1">Expanding the panel <a class="header-anchor" href="#expanding-the-panel" aria-label="Permalink to &quot;Expanding the panel&quot;">​</a></h2><p>Click the <strong>expand</strong> button (top-right corner of the panel) to open the chat interface in a larger modal. This provides a better experience for longer conversations. The modal shares the same state as the compact panel.</p><p><img src="'+r+'" alt="AI Context panel — expanded modal"></p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Your conversation is saved automatically. If you close the panel, refresh the page, or reopen the editor later, your chat history and last suggestions are restored.</p><h2 id="customizing-the-ai-prompt" tabindex="-1">Customizing the AI prompt <a class="header-anchor" href="#customizing-the-ai-prompt" aria-label="Permalink to &quot;Customizing the AI prompt&quot;">​</a></h2><p>By default, the Context Assistant uses a built-in system prompt optimized for editorial suggestions. You can customize it:</p><ol><li>Go to <strong>JEO → AI Configuration → Context Assistant</strong> tab.</li><li>Check <strong>&quot;Use a custom system prompt&quot;</strong>.</li><li>Edit the prompt in the textarea.</li><li>Save settings.</li></ol><p>When unchecked, the tab shows the default prompt in a read-only field for reference.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>An AI provider must be configured in <strong>JEO → AI</strong> (see <a href="./ai-settings">AI Settings</a>).</li><li>For best results, index your posts in the Knowledge Base (<strong>JEO → AI → Knowledge Base</strong> tab). The assistant uses RAG to find related articles from the vectorized archive.</li><li>The article must have at least 100 characters of content before the AI can generate suggestions. If the article is too short, the assistant will ask you to write more or specify what you want.</li></ul>',37)])])}const b=t(l,[["render",h]]);export{f as __pageData,b as default};
